import sys

def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    size = [0] * (N + 1)
    stack = [(1, -1, False)]

    while stack:
        node, parent, visited = stack.pop()
        if not visited:
            stack.append((node, parent, True))
            for neighbor in adj[node]:
                if neighbor != parent:
                    stack.append((neighbor, node, False))
        else:
            size[node] = 1
            for neighbor in adj[node]:
                if neighbor != parent:
                    size[node] += size[neighbor]

    children = adj[1]
    children_sizes = [size[child] for child in children]
    sum_sizes = sum(children_sizes)
    max_size = max(children_sizes)
    ans = (sum_sizes - max_size) + 1
    print(ans)

if __name__ == "__main__":
    main()
