        adj[v].append(u)

    steps_of = [0] * (N + 1)
    stack = [(1, None, False)]

    while stack:
        node, parent, visited = stack.pop()
        if not visited:
            stack.append((node, parent, True))
            for neighbor in adj[node]:
                if neighbor != parent:
                    stack.append((neighbor, node, False))
        else:
            sum_children = 0
            for neighbor in adj[node]:
                if neighbor != parent:
                    sum_children += steps_of[neighbor]
            steps_of[node] = sum_children + 1

    children_steps = []
    for neighbor in adj[1]:
        children_steps.append(steps_of[neighbor])

    sum_children = sum(children_steps)
    if not children_steps:
        print(1)
    else:
        max_child = max(children_steps)
        ans = (sum_children - max_child) + 1
        print(ans)

